# ==============================================================================# 085_COMMERCIAL_QUERY_ENGINE.py## IOTEC COMMERCIAL QUERY ENGINE## Missão:# Executar missões comerciais utilizando capacidades homologadas.## Fluxo:# Missão#   ↓# Provider Registry#   ↓# Adapter#   ↓# Consulta# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CommercialQueryEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_queries(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            query_id TEXT,            mission TEXT,            capability TEXT,            provider TEXT,            adapter TEXT,            segmento TEXT,            estado TEXT,            cidade TEXT,            porte TEXT,            status TEXT,            evidence TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _hash(self,payload):        raw=json.dumps(            payload,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def execute(        self,        mission,        capability,        provider,        adapter,        segmento,        estado,        cidade,        porte,        metadata=None    ):        metadata=metadata or {}        timestamp=datetime.utcnow().isoformat()        query_id=hashlib.md5(            f"{timestamp}{mission}".encode()        ).hexdigest()        payload={            "timestamp":timestamp,            "query_id":query_id,            "mission":mission,            "capability":capability,            "provider":provider,            "adapter":adapter,            "segmento":segmento,            "estado":estado,            "cidade":cidade,            "porte":porte,            "status":"READY_TO_EXECUTE",            "evidence":"Consulta preparada utilizando capacidade homologada.",            "metadata":metadata        }        assinatura=self._hash(payload)        self.conn.execute("""        INSERT INTO commercial_queries(            timestamp,            query_id,            mission,            capability,            provider,            adapter,            segmento,            estado,            cidade,            porte,            status,            evidence,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["timestamp"],            payload["query_id"],            payload["mission"],            payload["capability"],            payload["provider"],            payload["adapter"],            payload["segmento"],            payload["estado"],            payload["cidade"],            payload["porte"],            payload["status"],            payload["evidence"],            json.dumps(payload["metadata"],ensure_ascii=False),            assinatura        ))        self.conn.commit()        payload["hash"]=assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    engine=CommercialQueryEngine()    resultado=engine.execute(        mission="Captar empresas industriais",        capability="BASE_EMPRESARIAL",        provider="EMPRESARIAL_PROVIDER_001",        adapter="EMPRESARIAL_ADAPTER",        segmento="Industrial",        estado="CE",        cidade="Fortaleza",        porte="Médio",        metadata={            "origin":"084_PROVIDER_REGISTRY_ENGINE",            "priority":"ALTA"        }    )    print("="*80)    print("COMMERCIAL QUERY")    print("="*80)    for k,v in resultado.items():        print(f"{k:22}: {v}")    print("="*80)